package com.example.qldetai.feature.evaluation;
import com.example.qldetai.feature.academic.RegistrationPeriod; import com.example.qldetai.feature.identity.Lecturer; import com.example.qldetai.feature.project.ProjectAssignment; import jakarta.persistence.*; import java.time.LocalDateTime; import lombok.*;
@Entity @Table(name="evaluation_assignments") @Getter @Setter @NoArgsConstructor public class EvaluationAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assignment_id") private ProjectAssignment assignment; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="period_id") private RegistrationPeriod period; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="component_id") private AssessmentComponent component; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="rubric_id") private Rubric rubric; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="lecturer_id") private Lecturer lecturer; @Column(name="evaluator_role",nullable=false) private String evaluatorRole="REVIEWER"; @Enumerated(EnumType.STRING) @Column(nullable=false) private EvaluationStatus status=EvaluationStatus.ACTIVE; @Column(name="deadline_at",nullable=false) private LocalDateTime deadlineAt; @PrePersist void setDerivedPeriod() { if (period == null && assignment != null) period = assignment.getPeriod(); } }
